materials.vertexShader:
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

materials.fragmentShader:
uniform float uLightIntensity;
varying vec2 vUv;
void main() {
  // Dark charcoal and deep gray-green gradient matching 01.png
  vec3 darkCharcoal = vec3(0.008, 0.016, 0.020); // #020405
  vec3 deepGreen    = vec3(0.020, 0.042, 0.048); // #050b0c
  vec3 aquaGlow     = vec3(0.065, 0.145, 0.165);

  // Diagonal light shafts from top right
  float shaftAngle = vUv.x * 0.75 + vUv.y * 0.65;
  float shaft1 = sin(shaftAngle * 42.0) * 0.5 + 0.5;
  float shaft2 = sin((shaftAngle + 0.15) * 78.0) * 0.5 + 0.5;
  float rays = (shaft1 * 0.65 + shaft2 * 0.35) * smoothstep(0.40, 0.95, vUv.x) * smoothstep(0.30, 0.95, vUv.y);

  vec3 base = mix(darkCharcoal, deepGreen, vUv.x * 0.7 + vUv.y * 0.3);
  vec3 col = (base + aquaGlow * rays * 1.3) * uLightIntensity;
  gl_FragColor = vec4(col, 1.0);
}
